using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "RewardCustomEventSetup", menuName = "Data/BattleSceneSetups/Events/RewardCustomEventSetup", order = 0)]
public class RewardCustomEventSetup : CustomEventSetup
{
	[Header("Battle Setup")]
	[SerializeField]
	private RewardSetup rewardSetup;

	[SerializeField]
	private ClearingReward eventClearingReward;

	[SerializeField]
	private MapHandler mapHandler;

	public ClearingReward EventClearingReward => eventClearingReward;

	public override void SetupScene()
	{
		mapHandler.SetClearingReward(eventClearingReward, goToEndOfBattleState: false);
		rewardSetup.SetupScene();
	}
}
